import{at as e,it as t,n,vt as r}from"./chunks/framework.DbV_8hbX.js";var i=JSON.parse(`{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"en/reference/faq.md","filePath":"en/reference/faq.md","lastUpdated":1794405696000}`),a={name:`en/reference/faq.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to “FAQ”">​</a></h1><h2 id="do-i-need-to-configure-each-page" tabindex="-1">Do I need to configure each page? <a class="header-anchor" href="#do-i-need-to-configure-each-page" aria-label="Permalink to “Do I need to configure each page?”">​</a></h2><p>The shared tag automatically fetches the basic page information. There is no required per-page setting. Do check the contents of your JSON-LD and metadata.</p><h2 id="is-the-raw-number-of-seconds-on-a-page-treated-as-interest" tabindex="-1">Is the raw number of seconds on a page treated as interest? <a class="header-anchor" href="#is-the-raw-number-of-seconds-on-a-page-treated-as-interest" aria-label="Permalink to “Is the raw number of seconds on a page treated as interest?”">​</a></h2><p>Display time is an observed value. The API selects the views that met the minimum time, and interest is judged using context such as the page as well. It is not a conversion where longer means a higher purchase probability.</p><h2 id="does-ai-write-the-offer-text" tabindex="-1">Does AI write the offer text? <a class="header-anchor" href="#does-ai-write-the-offer-text" aria-label="Permalink to “Does AI write the offer text?”">​</a></h2><p>No. Text, images and JavaScript are registered in advance. The judgment questions built from your input are also assembled from a fixed template.</p><h2 id="is-what-you-want-to-tell-them-the-same-as-the-display-title" tabindex="-1">Is &quot;what you want to tell them&quot; the same as the display title? <a class="header-anchor" href="#is-what-you-want-to-tell-them-the-same-as-the-display-title" aria-label="Permalink to “Is &quot;what you want to tell them&quot; the same as the display title?”">​</a></h2><p>The former is input that describes the context for judging. The display title is the wording actually shown. The campaign name is yet another, administrative, name.</p><h2 id="can-one-user-work-on-several-sites" tabindex="-1">Can one user work on several sites? <a class="header-anchor" href="#can-one-user-work-on-several-sites" aria-label="Permalink to “Can one user work on several sites?”">​</a></h2><p>Yes. One account can belong to several sites and switch between them in the header. Permissions may differ from site to site.</p><h2 id="are-invitation-emails-sent-automatically" tabindex="-1">Are invitation emails sent automatically? <a class="header-anchor" href="#are-invitation-emails-sent-automatically" aria-label="Permalink to “Are invitation emails sent automatically?”">​</a></h2><p>In the initial version, you share the link manually. It is a separate feature from the email codes Cloudflare Access sends for entry.</p><h2 id="is-the-admin-token-no-longer-needed" tabindex="-1">Is the admin token no longer needed? <a class="header-anchor" href="#is-the-admin-token-no-longer-needed" aria-label="Permalink to “Is the admin token no longer needed?”">​</a></h2><p>It is used for the first superuser registration in production. It isn&#39;t used as a shared password after migration, or as a back door for recovery. It isn&#39;t needed for the first registration in a Preview linked to Access.</p><h2 id="is-the-display-count-shared-across-all-devices" tabindex="-1">Is the display count shared across all devices? <a class="header-anchor" href="#is-the-display-count-shared-across-all-devices" aria-label="Permalink to “Is the display count shared across all devices?”">​</a></h2><p>No. It is based on the valid history in the browser. It is not a scheme that tracks all devices with a server-side visitor ID.</p><h2 id="can-i-use-a-preview-passkey-in-production" tabindex="-1">Can I use a Preview passkey in production? <a class="header-anchor" href="#can-i-use-a-preview-passkey-in-production" aria-label="Permalink to “Can I use a Preview passkey in production?”">​</a></h2><p>The origin and the database differ, so the same registration isn&#39;t carried over as it is. You register separately in production.</p><h2 id="does-production-always-need-access-too" tabindex="-1">Does production always need Access too? <a class="header-anchor" href="#does-production-always-need-access-too" aria-label="Permalink to “Does production always need Access too?”">​</a></h2><p>The preview environment is protected by Access this time. The production admin console is protected by the app&#39;s passkeys and permissions, and you can also combine Access or similar as needed. Don&#39;t confuse it with the public scope of the delivery API.</p><h2 id="where-can-i-see-results-or-purchase-rates" tabindex="-1">Where can I see results or purchase rates? <a class="header-anchor" href="#where-can-i-see-results-or-purchase-rates" aria-label="Permalink to “Where can I see results or purchase rates?”">​</a></h2><p>Result aggregation and A/B tests are not provided at the moment. The home screen shows the setup status. It doesn&#39;t present Jev&#39;s judgment score as a result.</p><h2 id="where-can-i-edit-help" tabindex="-1">Where can I edit Help? <a class="header-anchor" href="#where-can-i-edit-help" aria-label="Permalink to “Where can I edit Help?”">​</a></h2><p>It is the Markdown under <code>help/</code> in the GitHub repository. You can suggest changes from each page&#39;s edit link, or through Issues. For the publishing steps, see <a href="./../operations/help-site">maintaining the Help site</a>.</p><h2 id="can-i-use-a-different-jev-api-key-per-site" tabindex="-1">Can I use a different Jev API key per site? <a class="header-anchor" href="#can-i-use-a-different-jev-api-key-per-site" aria-label="Permalink to “Can I use a different Jev API key per site?”">​</a></h2><p>Yes. Site admins and superusers can set it in <a href="./../guides/jev">Jev connection</a>. It is stored encrypted and the value is never shown again. You can also see the number of real Jev calls started, their results and latency, but this is not billing data.</p>`,27)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};